+      const instructions = typeof task.input.instructions === "string" ? task.input.instructions : "";
+      let result: AgentRunResult;
+
+      if (!delegatedAgentId) {
+        result = { content: "", error: "delegate_task requires an agent_id" };
+      } else if (!instructions) {
+        result = { content: "", error: "delegate_task requires instructions" };
+      } else {
+        result = yield* executeAgentConversation(
+          delegatedAgentId,
+          { ...request, message: instructions, requestId: `${request.requestId}:${delegatedAgentId}` },
+          null,
+          abortController,
+          debugMode,
+          pathWithCurrentAgent,
+          false,
+        );
+      }
+
+      const toolResult = createToolResultMessage(task.toolUseId, result, request.sessionId);
+      if (streamResponses) yield toolResult.response;
+      context.push({ role: "user", content: toolResult.serializedResult });
+    }
+  }
