interface AgentRunResult {
  content: string;
  error?: string;
}

interface DelegateTaskInput {
  agent_id?: unknown;
  instructions?: unknown;
}

const NO_DELEGATE_OUTPUT = "The delegated agent completed without producing textual output.";

function createToolUseMessage(
  response: ProviderResponse,
  toolUseId: string,
  sessionId?: string,
): StreamResponse {
  return {
    type: "claude_json",
    data: {
      type: "assistant",
      message: {
        type: "message",
        role: "assistant",
        content: [{
          type: "tool_use",
          id: toolUseId,
          name: response.toolName,
          input: response.toolInput || {},
        }],
      },
      session_id: sessionId,
    },
  };
}

function createToolResultMessage(
  toolUseId: string,
  result: AgentRunResult,
  sessionId?: string,
): { response: StreamResponse; serializedResult: string } {
  const toolResult = {
    type: "tool_result",
    is_error: Boolean(result.error),
    content: result.error || result.content || NO_DELEGATE_OUTPUT,
    tool_use_id: toolUseId,
  };

  return {
    response: {
      type: "claude_json",
      data: {
        type: "user",
        message: {
          role: "user",
          content: [toolResult],
        },
        session_id: sessionId,
      },
    },
    serializedResult: JSON.stringify(toolResult),
  };
}

/**
 * Runs an agent until it finishes without requesting delegate_task. A delegated
 * result is supplied as a tool_result and the delegating agent is then invoked
 * again, allowing delegation to nest to any depth.
 */
async function* executeAgentConversation(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean,
  delegationPath: Set<string>,
  streamResponses: boolean,
): AsyncGenerator<StreamResponse, AgentRunResult> {
  if (delegationPath.has(agentId)) {
    const error = `Circular delegation detected for agent '${agentId}'`;
    yield { type: "error", error };
    return { content: "", error };
  }

  const provider = globalRegistry.getProviderForAgent(agentId);
  const agentConfig = globalRegistry.getAgent(agentId);

  if (!provider || !agentConfig) {
    const error = `Agent '${agentId}' not found or provider not available`;
    // A missing delegation target is actionable by the delegator, but must also
    // be reported to the client rather than being silently hidden in the result.
    yield { type: "error", error };
    return { content: "", error };
  }

  // Handle special commands
  if (command?.command === "capture_screen") {
    yield* handleScreenCapture(agentId, request, command, abortController, debugMode);
    return { content: "Screenshot captured." };
  }

  // Build provider request
  const providerRequest: ProviderChatRequest = {
    message: request.message,
    sessionId: request.sessionId,
    requestId: request.requestId,
    workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
  };

  const pathWithCurrentAgent = new Set(delegationPath);
  pathWithCurrentAgent.add(agentId);
  const context = [...(providerRequest.context || [])];
  let accumulatedContent = "";
  let toolSequence = 0;

  while (true) {
    const delegatedTasks: Array<{ toolUseId: string; input: DelegateTaskInput }> = [];
    let runError: string | undefined;

    try {
      for await (const response of provider.executeChat({ ...providerRequest, context }, {
        debugMode,
        abortController,
        temperature: agentConfig.config?.temperature,
        maxTokens: agentConfig.config?.maxTokens,
